#include "window.h"
#include <algorithm>
static QJsonObject readJson(QString path){QFile f(path);if(!f.open(QIODevice::ReadOnly))return {};return QJsonDocument::fromJson(f.readAll()).object();}
static bool writeJson(QString path,QJsonObject object){QSaveFile f(path);if(!f.open(QIODevice::WriteOnly))return false;f.write(QJsonDocument(object).toJson());return f.commit();}
static QRect layerBounds(Layer* n){if(!n->group)return n->bounds;QRect result;for(auto& child:n->children)result=result.united(layerBounds(child.get()));return result;}
QString Window::proposedName(Layer* n,const QJsonObject& rules,QString mode,bool useDictionary)const{if(n->manual)return n->name;QString name=n->originalName;
    if(useDictionary&&!n->group)name=dictionaryName(name,rules,mode);
    if(directionSwitch->isChecked()&&settings.value(n->group?"direction-groups":"direction-layers",!n->group).toBool()){auto b=layerBounds(n);double center=b.isEmpty()?doc.width/2.:(b.left()+b.right()+1)/2.;QString key=qAbs(center-doc.width/2.)<=settings.value("direction-tolerance-px",20).toInt()?"M":center<doc.width/2.?"L":"R";QString suffix=settings.value("direction-"+key,key).toString();if(!suffix.isEmpty())name+=settings.value("direction-separator","_").toString()+suffix;}return name;}
void Window::naming(){for(auto n:flatten(doc.roots))n->name=proposedName(n,dictionary,dictionaryMatchMode,dictSwitch->isChecked());numbering.clear();numberManual.clear();numberingSelection.clear();refresh();}
bool Window::previewDictionary(const QJsonObject& rules,QString mode,bool confirm){QDialog dialog(this);dialog.setObjectName("dictionaryMatchPreview");dialog.setWindowTitle(QStringLiteral("词库同步预览"));dialog.resize(760,470);auto layout=new QVBoxLayout(&dialog);auto table=new QTableWidget(&dialog);table->setObjectName("dictionaryPreviewTable");table->setColumnCount(3);table->setHorizontalHeaderLabels({QStringLiteral("原名"),QStringLiteral("新名"),QStringLiteral("位置")});table->setEditTriggers(QAbstractItemView::NoEditTriggers);table->setSelectionBehavior(QAbstractItemView::SelectRows);table->horizontalHeader()->setSectionResizeMode(QHeaderView::Stretch);for(auto n:flatten(doc.roots)){QString next=proposedName(n,rules,mode,true);if(next==n->name)continue;QStringList path;for(auto parent=n->parent;parent;parent=parent->parent)path.prepend(parent->name);int row=table->rowCount();table->insertRow(row);table->setItem(row,0,new QTableWidgetItem(n->name));table->setItem(row,1,new QTableWidgetItem(next));table->setItem(row,2,new QTableWidgetItem(path.join(" / ")));}layout->addWidget(new QLabel(QStringLiteral("%1 项改名").arg(table->rowCount()),&dialog));layout->addWidget(table);auto buttons=new QDialogButtonBox(confirm?QDialogButtonBox::Ok|QDialogButtonBox::Cancel:QDialogButtonBox::Close,&dialog);if(confirm){buttons->button(QDialogButtonBox::Ok)->setText(QStringLiteral("确认应用"));buttons->button(QDialogButtonBox::Cancel)->setText(QStringLiteral("取消"));}else buttons->button(QDialogButtonBox::Close)->setText(QStringLiteral("关闭"));layout->addWidget(buttons);connect(buttons,&QDialogButtonBox::accepted,&dialog,&QDialog::accept);connect(buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);return dialog.exec()==QDialog::Accepted;}
void Window::directionSettings(){QDialog dialog(this);dialog.setWindowTitle(QStringLiteral("方向后缀设置"));dialog.setFixedWidth(480);auto layout=new QVBoxLayout(&dialog);layout->setContentsMargins(24,24,24,20);layout->setSpacing(16);auto form=new QFormLayout;form->setHorizontalSpacing(16);form->setVerticalSpacing(16);QHash<QString,QLineEdit*> suffixes;
    auto targets=new QWidget(&dialog);auto targetsLayout=new QHBoxLayout(targets);targetsLayout->setContentsMargins(0,0,0,0);targetsLayout->setSpacing(16);auto layers=new QCheckBox(QStringLiteral("图层"),targets),groups=new QCheckBox(QStringLiteral("文件夹"),targets);layers->setChecked(settings.value("direction-layers",true).toBool());groups->setChecked(settings.value("direction-groups",false).toBool());targetsLayout->addWidget(layers);targetsLayout->addWidget(groups);targetsLayout->addStretch();form->addRow(QStringLiteral("应用到"),targets);
    for(auto row:{qMakePair(QStringLiteral("屏幕左侧"),QString("L")),qMakePair(QStringLiteral("屏幕右侧"),QString("R")),qMakePair(QStringLiteral("中轴"),QString("M"))}){auto input=new QLineEdit(settings.value("direction-"+row.second,row.second).toString(),&dialog);suffixes.insert(row.second,input);form->addRow(row.first,input);}
    auto tolerance=new QSpinBox(&dialog);tolerance->setRange(0,100000);tolerance->setSuffix(" px");tolerance->setValue(settings.value("direction-tolerance-px",20).toInt());form->addRow(QStringLiteral("中轴偏差"),tolerance);
    layout->addLayout(form);auto buttons=new QDialogButtonBox(QDialogButtonBox::Ok|QDialogButtonBox::Cancel,&dialog);buttons->button(QDialogButtonBox::Ok)->setText(QStringLiteral("保存"));buttons->button(QDialogButtonBox::Cancel)->setText(QStringLiteral("取消"));layout->addWidget(buttons);connect(buttons,&QDialogButtonBox::accepted,&dialog,&QDialog::accept);connect(buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);
    if(dialog.exec()==QDialog::Accepted){bool changed=false;auto saveSetting=[&](QString key,QVariant value,QVariant fallback){if(settings.value(key,fallback)!=value)changed=true;settings.setValue(key,value);};for(auto it=suffixes.begin();it!=suffixes.end();++it)saveSetting("direction-"+it.key(),it.value()->text().trimmed(),it.key());saveSetting("direction-tolerance-px",tolerance->value(),20);saveSetting("direction-layers",layers->isChecked(),true);saveSetting("direction-groups",groups->isChecked(),false);if(changed)naming();}}
void editDictionary(Window&);
void Window::dictionarySettings(){editDictionary(*this);}
struct Entry{QJsonObject node;QString parent;int index;};
static QHash<QString,Entry> indexTree(QJsonArray roots){QHash<QString,Entry> index;std::function<void(QJsonArray,QString)> walk=[&](QJsonArray nodes,QString parent){for(int i=0;i<nodes.size();++i){auto n=nodes[i].toObject();QString id=n["id"].toString();index.insert(id,{n,parent,i});walk(n["children"].toArray(),id);}};walk(roots,{});return index;}
QJsonArray Window::changes()const{auto before=indexTree(baseline),after=indexTree(serializeLayers(doc.roots));QJsonArray out;auto add=[&](QString type,QString name,QString detail){out.append(QJsonObject{{"type",type},{"name",name},{"detail",detail}});};auto path=[&](const QHash<QString,Entry>& index,QString id){QStringList names;while(index.contains(id)){auto e=index[id];names.prepend(e.node["name"].toString());id=e.parent;}return names.isEmpty()?QStringLiteral("最外层"):names.join(" / ");};
    for(auto it=before.begin();it!=before.end();++it)if(!after.contains(it.key()))add(QStringLiteral("删除"),it.value().node["name"].toString(),it.value().node["group"].toBool()?QStringLiteral("文件夹"):QStringLiteral("图层"));
    for(auto n:flatten(doc.roots)){auto next=after[n->id];QString name=n->name;if(!before.contains(n->id)){add(QStringLiteral("新建"),name,(n->group?QStringLiteral("文件夹 · "):QStringLiteral("图层 · "))+path(after,next.parent));continue;}auto previous=before[n->id];if(previous.node["name"].toString()!=name)add(QStringLiteral("改名"),name,previous.node["name"].toString()+" → "+name);if(previous.node["hidden"].toBool()!=n->hidden)add(QStringLiteral("显隐"),name,n->hidden?QStringLiteral("显示 → 隐藏"):QStringLiteral("隐藏 → 显示"));if(previous.parent!=next.parent)add(QStringLiteral("移动"),name,path(before,previous.parent)+" → "+path(after,next.parent));
        else{QVector<QPair<int,QString>> a,b;for(auto it=before.begin();it!=before.end();++it)if(it.value().parent==previous.parent&&after.contains(it.key())&&after[it.key()].parent==previous.parent)a.append({it.value().index,it.key()});for(auto it=after.begin();it!=after.end();++it)if(it.value().parent==next.parent&&before.contains(it.key())&&before[it.key()].parent==next.parent)b.append({it.value().index,it.key()});std::sort(a.begin(),a.end());std::sort(b.begin(),b.end());int ai=-1,bi=-1;for(int i=0;i<a.size();++i)if(a[i].second==n->id)ai=i;for(int i=0;i<b.size();++i)if(b[i].second==n->id)bi=i;if(ai!=bi)add(QStringLiteral("排序"),name,QStringLiteral("第 %1 项 → 第 %2 项").arg(previous.index+1).arg(next.index+1));}
    }return out;}
void Window::save(bool saveAs){if(busy||doc.path.isEmpty()||QApplication::activeModalWidget())return;QDialog dialog(this);dialog.setObjectName("changesReview");dialog.setWindowTitle(QStringLiteral("所有改动"));dialog.resize(800,500);auto layout=new QVBoxLayout(&dialog);auto table=new QTableWidget(&dialog);table->setObjectName("changesTable");table->setColumnCount(3);table->setHorizontalHeaderLabels({QStringLiteral("改动"),QStringLiteral("名称"),QStringLiteral("详情")});table->setEditTriggers(QAbstractItemView::NoEditTriggers);table->horizontalHeader()->setSectionResizeMode(2,QHeaderView::Stretch);table->setColumnWidth(1,220);auto list=changes();table->setRowCount(list.size());for(int i=0;i<list.size();++i){auto n=list[i].toObject();table->setItem(i,0,new QTableWidgetItem(n["type"].toString()));table->setItem(i,1,new QTableWidgetItem(n["name"].toString()));table->setItem(i,2,new QTableWidgetItem(n["detail"].toString()));}layout->addWidget(table);auto buttons=new QDialogButtonBox(QDialogButtonBox::Ok|QDialogButtonBox::Cancel,&dialog);buttons->button(QDialogButtonBox::Ok)->setText(saveAs?QStringLiteral("确认另存为"):QStringLiteral("确认保存"));buttons->button(QDialogButtonBox::Cancel)->setText(QStringLiteral("取消"));layout->addWidget(buttons);connect(buttons,&QDialogButtonBox::accepted,&dialog,&QDialog::accept);connect(buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);if(dialog.exec()!=QDialog::Accepted)return;
    QFileInfo original(doc.path);QString base=original.absolutePath()+"/"+original.completeBaseName();QString suggested;int i=1;do{suggested=base+"_"+QString::number(i++)+".psd";}while(QFile::exists(suggested));QString output=saveAs?QFileDialog::getSaveFileName(this,QStringLiteral("另存为 PSD"),suggested,"Photoshop Files (*.psd)"):suggested;if(output.isEmpty())return;if(QFileInfo(output).suffix().toLower()!="psd")output+=".psd";if(QFile::exists(output)||QFileInfo(output).absoluteFilePath()==original.absoluteFilePath()){QMessageBox::warning(this,QStringLiteral("无法保存"),QStringLiteral("文件已存在，请使用新的文件名。"));return;}writeSave(output);}
void Window::writeSave(QString output){if(!writeJson(doc.workspace+"/save.json",QJsonObject{{"children",serializeLayers(doc.roots)}})){QMessageBox::critical(this,QStringLiteral("保存失败"),QStringLiteral("无法写入临时文件"));return;}setBusy(true);auto d=doc;QFutureWatcher<QImage>* render=new QFutureWatcher<QImage>(this);connect(render,&QFutureWatcher<QImage>::finished,this,[this,render,output]{auto image=render->result().convertToFormat(QImage::Format_RGBA8888);render->deleteLater();QFile file(doc.workspace+"/merged.rgba");if(image.isNull()||!file.open(QIODevice::WriteOnly)||file.write(reinterpret_cast<const char*>(image.constBits()),image.sizeInBytes())!=image.sizeInBytes()){file.close();setBusy(false);QMessageBox::critical(this,QStringLiteral("保存失败"),QStringLiteral("画布像素生成失败"));return;}file.close();startCodec("save",output,[this,output](bool ok,QString error){setBusy(false);if(!ok)QMessageBox::critical(this,QStringLiteral("保存失败"),error.left(1200));else{savePath=output;QMessageBox::information(this,QStringLiteral("保存完成"),QFileInfo(output).fileName());}});});render->setFuture(QtConcurrent::run([d]{return renderDocument(d,{0,0,double(d.width),double(d.height)},{d.width,d.height});}));}
void Window::numberingSettings(){
    QDialog dialog(this);dialog.setObjectName("numberingSettingsDialog");dialog.setWindowTitle(QStringLiteral("编号设置"));dialog.setFixedWidth(360);
    auto layout=new QVBoxLayout(&dialog);layout->setContentsMargins(20,20,20,16);layout->setSpacing(16);auto form=new QFormLayout;form->setSpacing(12);
    auto separator=new QLineEdit(settings.value("direction-separator","_").toString(),&dialog);separator->setObjectName("numberingSeparator");form->addRow(QStringLiteral("分隔符"),separator);
    auto style=new QComboBox(&dialog);style->setObjectName("numberingStyle");style->addItem(QStringLiteral("数字 1、2、3"),"numbers");style->addItem(QStringLiteral("字母 A、B、C"),"letters");style->setCurrentIndex(settings.value("numbering-style","numbers").toString()=="letters"?1:0);form->addRow(QStringLiteral("编号方式"),style);layout->addLayout(form);
    auto buttons=new QDialogButtonBox(QDialogButtonBox::Save|QDialogButtonBox::Cancel,&dialog);buttons->button(QDialogButtonBox::Save)->setText(QStringLiteral("保存"));buttons->button(QDialogButtonBox::Cancel)->setText(QStringLiteral("取消"));layout->addWidget(buttons);connect(buttons,&QDialogButtonBox::accepted,&dialog,&QDialog::accept);connect(buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);
    if(dialog.exec()==QDialog::Accepted){settings.setValue("direction-separator",separator->text());settings.setValue("numbering-style",style->currentData());}
}
